-- G29: independently controlled rollout stages with evidence gates and rollback.
create table public.generation_rollout_policies(id uuid primary key default gen_random_uuid(),policy_key text not null,version integer not null check(version>0),stage text not null check(stage in('off','internal','staff','pilot','broader')),enabled boolean not null default false,pilot_cohort_percent integer not null check(pilot_cohort_percent between 0 and 100),low_risk_topic_allowlist text[] not null,thresholds jsonb not null,active boolean not null default false,created_at timestamptz not null default now(),unique(policy_key,version));
insert into public.generation_rollout_policies(policy_key,version,stage,enabled,pilot_cohort_percent,low_risk_topic_allowlist,thresholds,active) values('on_demand_generation',1,'internal',false,0,array['nature','sport','science_stable'],'{"minimum_sessions":100,"minimum_qa_yield":0.8,"maximum_safety_failure_rate":0.005,"maximum_anomaly_rate":0.05,"maximum_escalation_rate":0.15,"maximum_p95_latency_ms":10000,"maximum_cost_per_completed_session":0.2,"minimum_zone_share":0.7}',true);
create table public.generation_rollout_metric_snapshots(id uuid primary key default gen_random_uuid(),policy_id uuid not null references public.generation_rollout_policies(id) on delete restrict,window_start timestamptz not null,window_end timestamptz not null,generation_rate numeric not null,reuse_rate numeric not null,qa_yield numeric not null,human_escalation_rate numeric not null,anomaly_rate numeric not null,safety_failure_rate numeric not null,cost_per_completed_session numeric not null,p95_latency_ms integer not null,normal_zone_share numeric not null,retrieval_metrics jsonb not null,package_completion_metrics jsonb not null,raw_counts jsonb not null,created_at timestamptz not null default now());
create table public.generation_launch_decisions(id uuid primary key default gen_random_uuid(),policy_id uuid not null references public.generation_rollout_policies(id) on delete restrict,metric_snapshot_id uuid not null references public.generation_rollout_metric_snapshots(id) on delete restrict,benchmark_report_id uuid not null references public.automation_release_reports(id) on delete restrict,decision text not null check(decision in('expand','hold','rollback')),from_stage text not null,to_stage text,reasons text[] not null,evidence_snapshot jsonb not null,decided_by uuid references public.profiles(id) on delete set null,created_at timestamptz not null default now());
create table public.generation_rollout_events(id uuid primary key default gen_random_uuid(),policy_id uuid not null references public.generation_rollout_policies(id) on delete restrict,event_type text not null check(event_type in('enabled','disabled','stage_changed','rollback_started','rollback_completed','kill_switch')),from_stage text,to_stage text,reason text not null,evidence_snapshot jsonb not null,actor_profile_id uuid references public.profiles(id) on delete set null,created_at timestamptz not null default now());
create table public.generation_weekly_audits(id uuid primary key default gen_random_uuid(),policy_id uuid not null references public.generation_rollout_policies(id) on delete restrict,week_start date not null,required_checks text[] not null,metric_snapshot_id uuid not null references public.generation_rollout_metric_snapshots(id) on delete restrict,benchmark_report_id uuid not null references public.automation_release_reports(id) on delete restrict,open_exception_count integer not null check(open_exception_count>=0),audit_payload jsonb not null,reviewer_profile_id uuid not null references public.profiles(id) on delete restrict,completed_at timestamptz not null,unique(policy_id,week_start));
create or replace function public.prevent_rollout_decision_mutation()returns trigger language plpgsql as $$begin raise exception 'rollout_decision_is_immutable';end$$;create trigger immutable_launch_decision before update or delete on public.generation_launch_decisions for each row execute function public.prevent_rollout_decision_mutation();create trigger immutable_weekly_audit before update or delete on public.generation_weekly_audits for each row execute function public.prevent_rollout_decision_mutation();
alter table public.generation_rollout_policies enable row level security;alter table public.generation_rollout_metric_snapshots enable row level security;alter table public.generation_launch_decisions enable row level security;alter table public.generation_rollout_events enable row level security;alter table public.generation_weekly_audits enable row level security;create policy rollout_policies_staff_read on public.generation_rollout_policies for select using(public.is_staff());create policy rollout_metrics_staff_read on public.generation_rollout_metric_snapshots for select using(public.is_staff());create policy launch_decisions_staff_read on public.generation_launch_decisions for select using(public.is_staff());create policy rollout_events_staff_read on public.generation_rollout_events for select using(public.is_staff());create policy weekly_audits_staff_read on public.generation_weekly_audits for select using(public.is_staff());grant select on public.generation_rollout_policies,public.generation_rollout_metric_snapshots,public.generation_launch_decisions,public.generation_rollout_events,public.generation_weekly_audits to authenticated;
